import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
// ------------------------------------------------------------------
// FONT LOADER
// ------------------------------------------------------------------
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// ------------------------------------------------------------------
// SCHEMA
// ------------------------------------------------------------------


export type InflationOverlayProps = Record<string, any>;

// ------------------------------------------------------------------
// COMPONENT
// ------------------------------------------------------------------
const InflationOverlay: React.FC<InflationOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 10,
  title = "ECONOMIC ALERT",
  subtitle = "RISING COSTS ANALYSIS",
  mainStatValue = "9.1%",
  mainStatLabel = "CPI INCREASE (YOY)",
  costItems = [
    "Energy: +41.6%",
    "Groceries: +11.9%",
    "Housing: +7.3%",
    "Transport: +14.2%"
  ],
  panelColor = "#1a1a1a",
  accentColor = "#e63946",
  textColor = "#ffffff",
}) => {
  // 1. Load Fonts
  useFontLoader(["Oswald", "Roboto"]);

  // 2. Config Hooks
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // 3. Logic & Calculations
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Layout Constants
  const panelWidth = width * 0.35;
  const padding = width * 0.03;

  // Animations
  
  // A. Panel Entrance (Slide from right)
  const panelEnter = spring({
    frame,
    fps,
    config: { damping: 14 },
    from: width,
    to: width - panelWidth,
  });

  // B. Graph Line Animation (Stroke Draw)
  // We'll create a zig-zag path that trends upwards
  const graphProgress = spring({
    frame: frame - 15, // Delay start
    fps,
    config: { stiffness: 50 },
  });
  
  // C. Title Fade/Slide
  const titleOpacity = interpolate(frame, [20, 40], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [20, 40], [20, 0], {
    easing: Easing.out(Easing.quad),
    extrapolateRight: "clamp",
  });

  // D. Main Stat Pop
  const statScale = spring({
    frame: frame - 30,
    fps,
    config: { stiffness: 100, damping: 10 },
  });

  // SVG Path for the "Rising Graph" background effect
  // Generates a path relative to the panel size
  const pathD = `
    M 0,${height * 0.6} 
    L ${panelWidth * 0.2},${height * 0.55} 
    L ${panelWidth * 0.4},${height * 0.58} 
    L ${panelWidth * 0.6},${height * 0.45} 
    L ${panelWidth * 0.8},${height * 0.48} 
    L ${panelWidth},${height * 0.2}
  `;
  const pathLength = panelWidth * 1.5; // Approximate length for stroke-dasharray

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "Roboto",
        overflow: "hidden",
      }}
    >
      {/* --- SIDE PANEL --- */}
      <div
        style={{
          position: "absolute",
          top: 0,
          bottom: 0,
          left: panelEnter,
          width: panelWidth,
          backgroundColor: panelColor,
          boxShadow: "-10px 0 30px rgba(0,0,0,0.5)",
          display: "flex",
          flexDirection: "column",
          padding: padding,
          boxSizing: "border-box",
          color: textColor,
          transition: "none",
        }}
      >
        {/* Background Grid Lines (Decoration) */}
        <AbsoluteFill style={{ zIndex: 0, opacity: 0.1 }}>
            {[1, 2, 3, 4, 5].map((i) => (
                <div
                    key={i}
                    style={{
                        position: "absolute",
                        top: `${i * 15}%`,
                        left: 0,
                        right: 0,
                        height: 1,
                        backgroundColor: textColor,
                    }}
                />
            ))}
        </AbsoluteFill>

        {/* Rising Graph Line (Background Graphic) */}
        <svg
          style={{
            position: "absolute",
            bottom: 0,
            left: 0,
            width: "100%",
            height: "100%",
            zIndex: 0,
            opacity: 0.4,
            overflow: "visible",
          }}
        >
          <path
            d={pathD}
            fill="none"
            stroke={accentColor}
            strokeWidth={8}
            strokeLinecap="round"
            strokeDasharray={pathLength}
            strokeDashoffset={interpolate(
              graphProgress,
              [0, 1],
              [pathLength, 0]
            )}
          />
          {/* Area under curve - fade in */}
          <path
             d={`${pathD} L ${panelWidth},${height} L 0,${height} Z`}
             fill={`url(#gradient-${frame})`}
             opacity={interpolate(frame, [20, 50], [0, 0.5], { extrapolateRight: "clamp" })}
          />
          <defs>
            <linearGradient id={`gradient-${frame}`} x1="0%" y1="0%" x2="0%" y2="100%">
                <stop offset="0%" stopColor={accentColor} stopOpacity={0.8} />
                <stop offset="100%" stopColor={accentColor} stopOpacity={0} />
            </linearGradient>
          </defs>
        </svg>

        {/* CONTENT CONTAINER (z-index 1) */}
        <div style={{ position: "relative", zIndex: 1, height: "100%", display: "flex", flexDirection: "column" }}>
            
            {/* Header Section */}
            <div style={{ opacity: titleOpacity, transform: `translateY(${titleY}px)` }}>
                <h2
                    style={{
                        margin: 0,
                        fontSize: width * 0.015,
                        fontWeight: 700,
                        textTransform: "uppercase",
                        letterSpacing: "0.1em",
                        color: accentColor,
                        fontFamily: "Oswald",
                    }}
                >
                    {title}
                </h2>
                <h1
                    style={{
                        margin: "10px 0 30px 0",
                        fontSize: width * 0.035,
                        fontWeight: 900,
                        lineHeight: 1,
                        fontFamily: "Oswald",
                        textTransform: "uppercase",
                    }}
                >
                    {subtitle}
                </h1>
            </div>

            {/* Main Big Statistic */}
            <div style={{ transform: `scale(${statScale})`, transformOrigin: "top left", marginBottom: 40 }}>
                <div 
                    style={{ 
                        fontSize: width * 0.08, 
                        fontWeight: 900, 
                        lineHeight: 0.9,
                        color: accentColor,
                        fontFamily: "Oswald",
                        textShadow: `0 0 20px ${accentColor}40`,
                    }}
                >
                    {mainStatValue}
                </div>
                <div 
                    style={{ 
                        fontSize: width * 0.012, 
                        fontWeight: 500,
                        opacity: 0.8,
                        marginTop: 10,
                        borderTop: `2px solid ${textColor}`,
                        paddingTop: 10,
                        display: "inline-block"
                    }}
                >
                    ▲ {mainStatLabel}
                </div>
            </div>

            {/* List of Rising Costs */}
            <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 15 }}>
                {costItems.map((item, index) => {
                    const delay = 45 + index * 5;
                    const itemProgress = spring({
                        frame: frame - delay,
                        fps,
                        config: { stiffness: 80, damping: 12 },
                    });
                    
                    const itemOpacity = interpolate(frame, [delay, delay + 10], [0, 1], { extrapolateRight: "clamp" });
                    const itemX = interpolate(itemProgress, [0, 1], [50, 0]);

                    // Split item string if it contains a colon for better formatting
                    const parts = item.split(":");
                    const label = parts[0];
                    const value = parts[1] || "";

                    return (
                        <div
                            key={index}
                            style={{
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "space-between",
                                backgroundColor: "rgba(255,255,255,0.05)",
                                padding: "12px 20px",
                                borderRadius: 8,
                                opacity: itemOpacity,
                                transform: `translateX(${itemX}px)`,
                                borderLeft: `4px solid ${accentColor}`,
                            }}
                        >
                            <span 
                                style={{ 
                                    fontSize: width * 0.012, 
                                    fontWeight: 700,
                                    textTransform: "uppercase" 
                                }}
                            >
                                {label}
                            </span>
                            <span 
                                style={{ 
                                    fontSize: width * 0.014, 
                                    fontWeight: 900, 
                                    color: accentColor,
                                    fontFamily: "Oswald"
                                }}
                            >
                                {value} ▲
                            </span>
                        </div>
                    );
                })}
            </div>
            
            {/* Footer / Time */}
            <div 
                style={{ 
                    marginTop: "auto", 
                    textAlign: "right", 
                    fontSize: width * 0.01, 
                    opacity: 0.5,
                    fontFamily: "monospace"
                }}
            >
                SOURCE: MARKET DATA API • LIVE UPDATE
            </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default InflationOverlay;